t-size:18px;color:#e3cf97;font-weight:500;line-height:20px}.skill-slot small{font-size:6px;letter-spacing:.3px;color:#d1cdb7;white-space:nowrap}.slot-key{position:absolute;top:3px;left:5px;font-size:6px;color:#a8ae9a}.cooldown{position:absolute;inset:auto 0 0;height:0;background:#07110ea8;transition:height .1s}.touch-controls{display:none}.crosshair{position:absolute;z-index:2;left:50%;top:50%;transform:translate(-50%,-50%);color:#f2e0a366;font-size:10px;pointer-events:none}.start-screen{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:rgba(8,14,12,.48);backdrop-filter:blur(2px);transition:opacity .7s,visibility .7s}.start-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-backdrop{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 46%,transparent 0 22%,rgba(5,12,10,.3) 68%),linear-gradient(90deg,rgba(6,15,11,.6),transparent 40% 60%,rgba(6,15,11,.45));pointer-events:none}.start-content{position:relative;text-align:center;width:min(440px,90vw);padding:28px 32px;background:linear-gradient(180deg,rgba(13,23,18,.75),rgba(12,21,17,.4));border:1px solid #d4c38b25;box-shadow:0 20px 70px #0005}.start-kicker{font-size:8px;letter-spacing:3px;color:#d2c28f}.start-content h1{font:clamp(54px,9vw,82px) Marcellus,serif;letter-spacing:11px;margin:12px 0 0 11px;color:#f4e7c1;text-shadow:0 0 38px #ebce8455}.start-sub{font-size:9px;letter-spacing:3px;color:#ddc990;margin:2px 0 16px}.start-rule{display:flex;gap:12px;align-items:center;justify-content:center;color:#d6bd77;font-size:11px}.start-rule i{width:70px;height:1px;background:linear-gradient(90deg,transparent,#d6bd7766)}.start-rule i:last-child{transform:rotate(180deg)}.start-copy{font:14px/1.65 Marcellus;color:#ddd9c8;margin:18px 0 22px}.start-content label{font-size:8px;letter-spacing:1.8px;color:#c9bd91;text-align:left;display:block;margin:10px 0}.start-content input{display:block;margin-top:7px;width:100%;height:37px;background:#101a15;border:1px solid #d1c4865