nel-button:disabled{opacity:.42;cursor:not-allowed}.panel-button.secondary{background:#ffffff10;color:#e3d8b4;border:1px solid #ddcc8238}.stat-row{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #ffffff12;font-size:11px;color:#c9cbb9}.stat-row b{color:#eddda9}.panel-tabs{display:flex;gap:6px;margin-bottom:14px}.panel-tabs button{padding:7px 10px;background:#ffffff08;border:1px solid #ffffff1a;color:#c9cbb9;font-size:9px;cursor:pointer}.panel-tabs button.selected{border-color:#dfc778;color:#f1dfa9}.menu-panel{text-align:center;width:min(380px,92vw);padding:36px}.menu-panel h2{font:26px Marcellus;color:#ecdfbc;margin:13px 0}.menu-panel p{color:#b6b9aa;font-size:11px}.menu-row{display:flex;align-items:center;gap:12px;width:100%;padding:12px 9px;margin-top:8px;text-align:left;background:#ffffff08;border:1px solid #ffffff17;color:#ddce9d;cursor:pointer}.menu-row span{flex:1;color:#e4dfca;font-size:11px}.menu-panel>small{display:block;color:#8f9b8e;font-size:8px;margin-top:20px}.settings-row{display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-bottom:1px solid #ffffff12;color:#d5d2c3;font-size:11px}.settings-row input{accent-color:#d6bd77}.toast.error{border-color:#bc7466;color:#e3a299}
@media(max-width:850px){.topbar{padding:10px 14px;gap:12px;height:70px}.brand-mark{min-width:auto}.brand-mark b{font-size:15px}.brand-mark small{font-size:6px}.player-card{min-width:125px}.resource-stack{width:116px}.world-status{padding-left:10px}.world-status small{display:none}.quest-card{left:14px;top:82px;width:225px}.map-card{right:14px;top:82px;width:160px}.mini-map{height:85px}.bottom-ui{padding:8px 12px;height:82px}.left-actions,.right-actions{width:136px;gap:5px}.utility-button{width:42px;height:46px}.skill-slot{width:53px;height:47px}.combat-hint{bottom:68px}.hotbar{bottom:10px}.interaction-prompt{bottom:100px}}
@media(max-width:600px){#game-shell{min-height:480px}.topbar{height:59px;gap:9px;padding:7px 10px}.brand-glyph{font-size:22px}.brand-mark{gap:5px}.brand-mark b{font-size:12px;letter-spacing:2px}.brand-mark small{font-size:5px;letter-spacing:1px}.player-card{min-width:0;gap:6px}.portrait{width:30px;height:30px}.player-meta strong{font-size:11px}.player-meta span{display:none}.player-meta .level-line{margin-top:3px}.xp-track{width:47px}.resource-stack{width:88px;gap:7px}.resource{grid-template-columns:1fr;gap:2px;font-size:6px}.resource>div{width:100%;height:4px}.resource b{top:0;right:0;font-size:6px}.world-status{display:none}.icon-button{width:29px;height:29px;font-size:14px}.quest-card{left:9px;top:67px;width:185px;padding:10px}.quest-card h3{font-size:13px;margin:7px 0 4px}.quest-card p{font-size:8px;margin-bottom:8px}.quest-card>small{font-size:7px}.map-card{top:67px;right:9px;width:118px;padding:8px}.map-head,.map-foot{font-size:6px}.mini-map{height:68px;margin:6px 0}.bottom-ui{height:72px;padding:6px 8px}.left-actions,.right-actions{width:74px;gap:4px}.utility-button{height:39px;width:34px}.utility-button span{font-size:15px}.utility-button small{font-size:5px}.right-actions .utility-button:nth-child(2){display:none}.skill-slot{width:43px;height:43px}.hotbar{gap:3px;bottom:8px}.skill-slot b{font-size:15px}.skill-slot small{font-size:5px}.slot-key{font-size:5px}.combat-hint{display:none}.interaction-prompt{bottom:84px;font-size:9px}.touch-controls{display:block;position:absolute;inset:0;z-index:3;pointer-events:none}.stick{position:absolute;bottom:91px;left:20px;width:98px;height:98px;border-radius:50%;background:#101a1577;border:1px solid #e4d49444;pointer-events:auto;touch-action:none}.stick i{position:absolute;width:37px;height:37px;border-radius:50%;background:#dfd09a77;border:1px solid #f1e0a788;left:30px;top:30px}.touch-buttons{position:absolute;right:15px;bottom:88px;display:grid;grid-template-columns:repeat(2,46px);gap:8px;pointer-events:auto}.touch-buttons button{width:46px;height:46px;border-radius:50%;background:#17251dcc;border:1px solid #ddca8466;color:#e6d39a;font-size:18px;touch-action:manipulation}.crosshair{display:none}.start-content{padding:23px 20px}.start-copy{font-size:12px}.game-panel{padding:24px 18px}.panel-title{font-size:24px}.menu-panel{padding:30px 22px}}

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=document.createElement('canvas');$('#world').append(canvas);const ctx=canvas.getContext('2d');
const W=2600,H=1900,keys=new Set(),saveKey='eteria-save-v1';let viewW=innerWidth,viewH=innerHeight,dpr=1,last=0,toastTimer,menuOpen=false,panelOpen=false;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let state={name:'Aster',mark:'✦',x:1270,y:1020,hp:100,maxHp:100,mp:50,maxMp:50,level:1,xp:0,gold:18,herbs:0,ore:0,wood:0,essence:0,slimes:0,waystone:false,questDone:false,discovered:[],stats:{strength:5,agility:5,intelligence:5,vitality:5,dexterity:5,wisdom:5,luck:5},inventory:['Wayfarer’s blade','Worn mantle','Field ration'],day:0,craft:0,profession:0,settings:{sound:true,particles:true}};
try{const old=JSON.parse(localStorage.getItem(saveKey));if(old&&old.v===1)state={...state,...old.data,x:clamp(old.data.x||1270,80,W-80),y:clamp(old.data.y||1020,80,H-80)}}catch(e){}
let player={x:state.x,y:state.y,face:0,speed:210,attack:0,dodge:0,guard:false,flash:0,step:0};
let mobs=[];for(let i=0;i<7;i++)mobs.push({kind:i===5?'mossback':'gloamling',x:rand(850,1650),y:rand(650,1250),homeX:0,homeY:0,hp:i===5?95:42,max:i===5?95:42,phase:'idle',timer:rand(0,3),hit:0,attack:0,dead:false,seed:rand(0,8)});mobs.forEach(m=>{m.homeX=m.x;m.homeY=m.y});
const nodes=[{type:'waystone',x:1458,y:916,name:'Old Waystone',used:false},{type:'npc',x:1127,y:1155,name:'Mira, the wayfarer'},{type:'herb',x:1560,y:1100,name:'Moonfern'},{type:'herb',x:1015,y:880,name:'Moonfern'},{type:'ore',x:1700,y:950,name:'Copper outcrop'},{type:'wood',x:900,y:1190,name:'Fallen bough'},{type:'chest',x:1770,y:1150,name:'Moss-covered coffer',used:false},{type:'lore',x:1540,y:804,name:'Carved marker',used:false}];
let particles=[];const sound={ctx:null,play(freq=260,duration=.08,type='sine'){if(!state.settings.sound)return;try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();let o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration)}catch(e){}}};
function resize(){viewW=innerWidth;viewH=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=viewW*dpr;canvas.height=viewH*dpr;canvas.style.width=viewW+'px';canvas.style.height=viewH+'px'}addEventListener('resize',resize);resize();
function save(){state.x=player.x;state.y=player.y;try{localStorage.setItem(saveKey,JSON.stringify({v:1,data:state}))}catch(e){}}
function notify(msg,error=false){let el=$('#toast');el.textContent=msg;el.classList.toggle('error',error);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function xpGain(n,activity='exploration'){state.xp+=n;if(activity==='exploration')state.stats.wisdom++;if(activity==='craft')state.profession++;if(activity==='combat')state.stats.strength++;let needed=80+state.level*45;if(state.xp>=needed){state.xp-=needed;state.level++;state.maxHp+=12;state.hp=state.maxHp;state.maxMp+=5;state.mp=state.maxMp;notify(`Level ${state.level} · your path unfolds`);sound.play(540,.3)}updateHud();save()}
