function drawAtmosphere(now){let night=(state.day%4===2);if(night){ctx.fillStyle='#10193738';ctx.fillRect(0,0,viewW,viewH)}let gl=ctx.createRadialGradient(viewW*.5,viewH*.42,30,viewW*.5,viewH*.42,Math.max(viewW,viewH)*.72);gl.addColorStop(0,'#e4d28a08');gl.addColorStop(1,'#0a130f4c');ctx.fillStyle=gl;ctx.fillRect(0,0,viewW,viewH);if(state.day%4===1){ctx.fillStyle='#d5dfd022';ctx.fillRect(0,0,viewW,viewH)}}
function drawEnemyLabels(cx,cy){let holder=$('#enemy-bars');holder.innerHTML='';for(const m of mobs){if(m.dead||dist(m,player)>330)continue;let x=viewW/2+(m.x-cx),y=viewH/2+(m.y-cy)-35;if(x<20||y<30||x>viewW-20)continue;let el=document.createElement('div');el.className='enemy-label';el.style.left=x+'px';el.style.top=y+'px';el.innerHTML=`${m.kind==='mossback'?'Mossback':'Gloamling'} <div class="bar"><i style="width:${100*m.hp/m.max}%"></i></div>`;holder.append(el)}}
function addBurst(x,y,color,n=8){if(!state.settings.particles)return;for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-60,60),vy:rand(-100,20),life:rand(.3,.7),max:.7,r:rand(1,3),color})}
function nearest(){let found=null,best=72;for(const n of nodes){if((n.type==='chest'||n.type==='lore')&&n.used)continue;if(n.type==='waystone'&&state.waystone)continue;let d=dist(n,player);if(d<best){found=n;best=d}}return found}
function refreshPrompt(){let n=nearest(),box=$('#interaction-prompt');if(!n||!$('#start-screen').classList.contains('hidden')||panelOpen||menuOpen){box.classList.remove('visible');return}let text=n.type==='waystone'?'Awaken the old waystone':n.type==='npc'?'Speak with Mira':n.type==='herb'?'Gather moonfern':n.type==='ore'?'Mine copper':n.type==='wood'?'Collect fallen wood':n.type==='chest'?'Open moss-covered coffer':'Read the carved marker';$('#interaction-text').textContent=text;box.classList.add('visible')}
function interact(){let n=nearest();if(!n)return;if(n.type==='waystone'){state.waystone=true;state.discovered.push('Old Waystone');notify('The waystone answers · a light stirs in the hollow');sound.play(420,.35,'triangle');addBurst(n.x,n.y,'#f1df9b',24);xpGain(35);updateHud()}else if(n.type==='npc'){openPanel('merchant')}else if(n.type==='herb'){state.herbs++;state.inventory.push('Moonfern');notify('Gathered moonfern · useful for a field tonic');xpGain(12);nodes.splice(nodes.indexOf(n),1);save()}else if(n.type==='ore'){state.ore++;state.inventory.push('Copper ore');notify('Mined copper ore');xpGain(15,'craft');nodes.splice(nodes.indexOf(n),1);save()}else if(n.type==='wood'){state.wood++;state.inventory.push('Heartwood');notify('Collected heartwood');xpGain(10,'craft');nodes.splice(nodes.indexOf(n),1);save()}else if(n.type==='chest'){n.used=true;state.gold+=24;state.essence++;state.inventory.push('Dawn-thread charm');notify('Found 24 crowns and a Dawn-thread charm');xpGain(30);save()}else if(n.type==='lore'){n.used=true;state.discovered.push('The names beneath the moss');notify('Lore discovered · “We were not the first light.”');xpGain(25);openPanel('lore');save()}updateHud();refreshPrompt()}
function strike(type='attack'){if(panelOpen||menuOpen||!$('#start-screen').classList.contains('hidden'))return;if(type==='dodge'){if(player.dodge>0)return;player.dodge=.38;player.speed=540;player.face=player.face;state.stats.agility++;sound.play(180,.13,'triangle');addBurst(player.x,player.y,'#bedacb',8);setTimeout(()=>player.speed=210,380);return}if(type==='block'){player.guard=true;setTimeout(()=>player.guard=false,650);return}if(type==='spell'&&player.spellCd>0)return;if(type==='spell'&&state.mp<12){notify('Not enough essence',true);return}if(type==='spell'){state.mp-=12;player.spellCd=2.8}player.attack=type==='heavy'?.38:.23;sound.play(type==='heavy'?110:type==='spell'?600:260,.12,type==='heavy'?'sawtooth':'triangle');let range=type==='heavy'?82:type==='spell'?260:62,damage=type==='heavy'?31:type==='spell'?34:17;let candidates=mobs.filter(m=>!m.dead&&dist(m,player)<range&& (type==='spell'||Math.abs(Math.atan2(m.y-player.y,m.x-player.x)-player.face)<1.9));let target=candidates.sort((a,b)=>dist(a,player)-dist(b,player))[0];if(target){if(type==='spell'){let angle=Math.atan2(target.y-player.y,target.x-player.x);for(let t=0;t<12;t++)particles.push({x:player.x+Math.cos(angle)*t*12,y:player.y+Math.sin(angle)*t*12,vx:0,vy:0,life:.3,max:.3,r:4,color:'#ffbe73'})}target.hp-=damage;target.hit=.18;addBurst(target.x,target.y,type==='spell'?'#ffbd73':'#e8d797',9);if(target.hp<=0){target.dead=true;state.slimes++;let loot=target.kind==='mossback'?'Mossback hide':'Gloam gel';state.inventory.push(loot);if(Math.random()<.45){state.gold+=3;notify(`${loot} · +${3} crowns`)}else notify(`${loot} collected`);xpGain(target.kind==='mossback'?55:28,'combat');if(state.waystone&&state.slimes>=3&&!state.questDone){state.questDone=true;state.gold+=35;state.inventory.push('Hollowlight sigil');notify('Quest complete · Hollowlight sigil earned');xpGain(80)}save()}else sound.play(100,.05,'square')}else if(type!=='spell'){}updateHud()}
function update(dt,now){if($('#start-screen').classList.contains('hidden')&&!panelOpen&&!menuOpen){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(touchVector){dx+=touchVector.x;dy+=touchVector.y}let l=Math.hypot(dx,dy)||1;if(dx||dy){player.x=clamp(player.x+dx/l*player.speed*dt,30,W-30);player.y=clamp(player.y+dy/l*player.speed*dt,30,H-30);player.face=Math.atan2(dy,dx);player.step+=dt*12;if(Math.random()<dt*2)addBurst(player.x,player.y+8,'#d7cf8a',1)}if(keys.has('f'))player.guard=true;else if(!touchGuard)player.guard=false;
for(const m of mobs){if(m.dead)continue;m.hit=Math.max(0,m.hit-dt);m.attack=Math.max(0,m.attack-dt);let d=dist(m,player);m.timer-=dt;if(d<205){if(d>31){m.x+=(player.x-m.x)/d*48*dt;m.y+=(player.y-m.y)/d*48*dt}else if(m.timer<=0){m.attack=.45;m.timer=1.5;if(player.dodge<=0){let dmg=player.guard?2:11;state.hp=Math.max(0,state.hp-dmg);player.flash=.2;notify(player.guard?'Guard deflects the strike':'A gloamling strikes you',!player.guard);sound.play(90,.12,'square');if(!state.hp){state.hp=state.maxHp;player.x=1270;player.y=1020;state.gold=Math.max(0,state.gold-5);notify('You wake by the old trail · 5 crowns lost',true)}}}}else if(d>260){m.x+=(m.homeX-m.x)/Math.max(d,1)*18*dt;m.y+=(m.homeY-m.y)/Math.max(d,1)*18*dt}else if(m.timer<=0){m.x+=rand(-35,35);m.y+=rand(-35,35);m.timer=rand(1,4)}}player.attack=Math.max(0,player.attack-dt);player.dodge=Math.max(0,player.dodge-dt);player.spellCd=Math.max(0,(player.spellCd||0)-dt);state.mp=Math.min(state.maxMp,state.mp+dt*1.1);state.day+=dt*.003;particles=particles.filter(p=>p.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vy+=30*dt}updateHud()}let cx=clamp(player.x,viewW/2,W-viewW/2),cy=clamp(player.y,viewH/2,H-viewH/2);if(viewW>W)cx=W/2;if(viewH>H)cy=H/2;drawWorld(cx,cy,now);refreshPrompt()}
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt,now);requestAnimationFrame(frame)}requestAnimationFrame(frame);

