function panelHeader(title,sub){return `<div class="eyebrow">FIELD RECORD · VERDANT REACH</div><h2 class="panel-title">${title}</h2><p class="panel-sub">${sub}</p>`}
function openPanel(type){panelOpen=true;$('#panel-overlay').classList.add('open');let c=$('#panel-content');if(type==='character'){c.innerHTML=panelHeader(state.name+' · '+$('#hud-title').textContent,`Level ${state.level} wayfarer · your path follows your choices.`)+`<div class="panel-grid"><div class="stat-card"><b>ATTRIBUTES</b>${Object.entries(state.stats).map(([k,v])=>`<div class="stat-row"><span>${k[0].toUpperCase()+k.slice(1)}</span><b>${v}</b></div>`).join('')}</div><div class="stat-card"><b>FIELD RECORD</b><div class="stat-row"><span>Creatures defeated</span><b>${state.slimes}</b></div><div class="stat-row"><span>Discoveries</span><b>${state.discovered.length}</b></div><div class="stat-row"><span>Artisan practice</span><b>${state.profession}</b></div><div class="stat-row"><span>Health / Essence</span><b>${state.maxHp} / ${state.maxMp}</b></div><p class="panel-sub">No fixed class. Use blades, spells, craft, and explore to shape your title.</p></div></div>`}
else if(type==='inventory'){let counts={};state.inventory.forEach(i=>counts[i]=(counts[i]||0)+1);c.innerHTML=panelHeader('Wayfarer’s pack',`${state.inventory.length} items · ${state.gold} crowns · local single-player economy`)+`<div class="panel-grid">${Object.entries(counts).map(([name,n])=>`<div class="item-card"><b>${name}${n>1?' ×'+n:''}</b><small>${itemDescription(name)}</small>${name==='Field ration'?'<button class="panel-button" data-action="use-ration">USE · RESTORE 35 VITALITY</button>':''}</div>`).join('')||'<p class="panel-sub">Your pack is empty.</p>'}</div>`}
else if(type==='craft'){c.innerHTML=panelHeader('Camp craft',`Practice ${state.profession} · recipes use materials you gather in the Reach.`)+`<div class="panel-grid"><div class="recipe-card"><b>Field tonic</b><small>Restore 40 vitality · requires 1 Moonfern</small><button class="panel-button" data-action="craft-tonic" ${state.herbs<1?'disabled':''}>BREW · 1 MOONFERN</button></div><div class="recipe-card"><b>Wayfarer’s edge</b><small>A simple sharpened blade · requires 2 Copper ore + 1 Heartwood</small><button class="panel-button" data-action="craft-blade" ${state.ore<2||state.wood<1?'disabled':''}>FORGE WEAPON</button></div><div class="recipe-card"><b>Ember focus</b><small>Increase maximum essence · requires 1 essence + 1 Moonfern</small><button class="panel-button" data-action="craft-focus" ${state.essence<1||state.herbs<1?'disabled':''}>WEAVE FOCUS</button></div><div class="recipe-card"><b>Materials</b><small>Moonfern ${state.herbs} · Copper ${state.ore} · Heartwood ${state.wood} · Essence ${state.essence}</small></div></div>`}
else if(type==='merchant'){c.innerHTML=panelHeader('Mira’s trail cart','“Every road is kinder with a warm meal. Take what you need.”')+`<div class="panel-grid"><div class="item-card"><b>Field ration</b><small>Restore 35 vitality · ${8} crowns</small><button class="panel-button" data-action="buy-ration" ${state.gold<8?'disabled':''}>BUY · 8 CROWNS</button></div><div class="item-card"><b>Traveler’s tonic</b><small>Restore 40 vitality · ${12} crowns</small><button class="panel-button" data-action="buy-tonic" ${state.gold<12?'disabled':''}>BUY · 12 CROWNS</button></div><div class="item-card"><b>Sell field goods</b><small>Trade one gathered material for 4 crowns. Mira keeps a local ledger.</small><button class="panel-button secondary" data-action="sell-goods" ${state.herbs+state.ore+state.wood<1?'disabled':''}>SELL ONE MATERIAL</button></div><div class="lore-card"><small>“I remember who shares a fire. You’ve helped ${state.discovered.includes('Mira’s trust')?'me before':'make this road safer'}.”</small></div></div>`}
else if(type==='lore'){c.innerHTML=panelHeader('Names beneath the moss','An inscription, worn smooth except where a careful hand kept tracing the same words.')+`<div class="lore-card"><p class="panel-sub" style="font:16px/1.8 Marcellus;color:#dfd3ad">“When the hollow forgets its song, lend it yours.<br>When the old light wakes, do not ask whom it chose.<br>We were all once strangers beneath the same sky.”</p></div><button class="panel-button" data-action="close-panel">CARRY THE WORDS</button>`}
else if(type==='map'){c.innerHTML=panelHeader('The Unwritten Reach','Your chart grows as the land reveals its shape.')+`<div style="height:260px;position:relative;border:1px solid #d5c78455;background:radial-gradient(ellipse at 50% 55%,#6a7750 0 16%,transparent 17%),radial-gradient(ellipse at 20% 20%,#3b5c42 0 28%,transparent 30%),radial-gradient(ellipse at 79% 19%,#28453b 0 30%,transparent 32%),linear-gradient(140deg,#385339,#263d34);overflow:hidden"><div style="position:absolute;inset:30px;background:linear-gradient(150deg,transparent 47%,#afa47b 48% 51%,transparent 52%)"></div><b style="position:absolute;left:48%;top:48%;color:#edda97">${state.mark}</b>${state.waystone?'<span style="position:absolute;left:55%;top:58%;color:#ffdc86">✦</span>':''}<span style="position:absolute;left:43%;top:66%;font:11px Marcellus">VERDANT REACH</span><span style="position:absolute;right:13px;top:10px;color:#d9d2b5">N ↑</span></div><p class="panel-sub">${state.discovered.length} discoveries · Explore beyond the trail to reveal more.</p>`}
else if(type==='journal'){c.innerHTML=panelHeader('Field journal','A record of the things the wild has taught you.')+`<div class="lore-card"><b>${state.questDone?'✦ A Light in the Hollow · COMPLETE':state.waystone?'◈ A Light in the Hollow · IN PROGRESS':'◇ A Light in the Hollow · UNCHARTED'}</b><p class="panel-sub">${state.questDone?'Mira entrusted you with the Hollowlight sigil. The stone’s song carries farther now.':state.waystone?`Defeat three gloamlings drawn to the awakened waystone. (${Math.min(state.slimes,3)} / 3)`:'Find the old waystone beneath the bent elder. A pale glow marks the ancient trail.'}</p><p class="panel-sub">Rewards: experience, crowns, a unique sigil, and a little more of Eteria’s story.</p></div><div class="panel-grid" style="margin-top:10px">${state.discovered.map(x=>`<div class="item-card"><b>✧ ${x}</b><small>Recorded in your field journal</small></div>`).join('')||'<div class="item-card"><b>No discoveries yet</b><small>Curiosity is its own compass.</small></div>'}</div>`}
else if(type==='settings'){c.innerHTML=panelHeader('Journey settings','Preferences are saved on this device.')+`<div class="settings-row"><span>Sound effects</span><input type="checkbox" data-setting="sound" ${state.settings.sound?'checked':''}></div><div class="settings-row"><span>Combat particles</span><input type="checkbox" data-setting="particles" ${state.settings.particles?'checked':''}></div><div class="settings-row"><span>Keyboard</span><span>WASD move · Space strike · Q heavy · R spell · E interact</span></div><div class="settings-row"><span>Touch</span><span>Left stick to move · right buttons to act</span></div><button class="panel-button secondary" data-action="close-panel">DONE</button>`}
$('#panel-overlay').classList.add('open')}
function itemDescription(name){return ({'Wayfarer’s blade':'A humble blade, balanced for the long road.','Worn mantle':'Weathered linen, patched more often than replaced.','Field ration':'A small meal for the miles ahead.','Moonfern':'A silver-veined herb that holds a little moonlight.','Copper ore':'Raw copper from the old creek bed.','Heartwood':'A fallen branch from an elder tree.','Gloam gel':'Cool, translucent residue from a defeated gloamling.','Mossback hide':'Tough hide from a shy mossback.','Dawn-thread charm':'A unique charm. Once hidden beneath the old stone.','Hollowlight sigil':'Unique · the waystone’s warmth, carried with you.'})[name]||'A useful find from the Unwritten Reach.'}

