function itemDescription(name){return ({'Wayfarer’s blade':'A humble blade, balanced for the long road.','Worn mantle':'Weathered linen, patched more often than replaced.','Field ration':'A small meal for the miles ahead.','Traveler’s tonic':'A field-made tonic that restores vitality.','Field tonic':'A field-made tonic that restores vitality.','Moonfern':'A silver-veined herb that holds a little moonlight.','Copper ore':'Raw copper from the old creek bed.','Heartwood':'A fallen branch from an elder tree.','Gloam gel':'Cool, translucent residue from a defeated gloamling.','Mossback hide':'Tough hide from a shy mossback.','Dawn-thread charm':'A unique charm. Once hidden beneath the old stone.','Hollowlight sigil':'Unique · the waystone’s warmth, carried with you.','Wayfarer’s edge':'A sharpened blade for the long road.','Ember focus':'A woven focus that holds more essence.'})[name]||'A useful find from the Unwritten Reach.'}

function closePanel(){panelOpen=false;$('#panel-overlay').classList.remove('open');refreshPrompt()}
function closeMenu(){menuOpen=false;$('#menu-overlay').classList.remove('open');refreshPrompt()}
function openMenu(){if(!$('#start-screen').classList.contains('hidden'))return;closePanel();menuOpen=true;$('#menu-overlay').classList.add('open')}
function act(action){if(action==='attack'||action==='heavy'||action==='spell'||action==='dodge'){strike(action);return}if(action==='block'){player.guard=true;return}if(action==='close-panel'){closePanel();return}if(action==='use-ration'){let item=state.inventory.includes('Field ration')?'Field ration':state.inventory.includes('Field tonic')?'Field tonic':state.inventory.includes('Traveler’s tonic')?'Traveler’s tonic':null;if(!item){notify('No restorative item in your pack',true);return}state.inventory.splice(state.inventory.indexOf(item),1);state.hp=Math.min(state.maxHp,state.hp+(item==='Field ration'?35:40));notify(`${item} used · vitality restored`);save();updateHud();openPanel('inventory');return}if(action==='craft-tonic'&&state.herbs>=1){state.herbs--;state.inventory.splice(state.inventory.indexOf('Moonfern'),1);state.inventory.push('Field tonic');state.craft++;xpGain(18,'craft');notify('Field tonic brewed');openPanel('craft')}else if(action==='craft-blade'&&state.ore>=2&&state.wood>=1){state.ore-=2;state.wood--;state.inventory.splice(state.inventory.indexOf('Copper ore'),2);state.inventory.splice(state.inventory.indexOf('Heartwood'),1);state.inventory.push('Wayfarer’s edge');state.craft++;xpGain(25,'craft');notify('Wayfarer’s edge forged');openPanel('craft')}else if(action==='craft-focus'&&state.essence>=1&&state.herbs>=1){state.essence--;state.herbs--;state.inventory.splice(state.inventory.indexOf('Moonfern'),1);state.maxMp+=12;state.mp=state.maxMp;state.inventory.push('Ember focus');state.craft++;xpGain(25,'craft');notify('Ember focus woven · maximum essence increased');openPanel('craft')}else if(action==='buy-ration'&&state.gold>=8){state.gold-=8;state.inventory.push('Field ration');notify('Field ration purchased');save();openPanel('merchant')}else if(action==='buy-tonic'&&state.gold>=12){state.gold-=12;state.inventory.push('Traveler’s tonic');notify('Traveler’s tonic purchased');save();openPanel('merchant')}else if(action==='sell-goods'){let type=state.herbs?'herbs':state.ore?'ore':'wood',item=type==='herbs'?'Moonfern':type==='ore'?'Copper ore':'Heartwood';state[type]--;let i=state.inventory.indexOf(item);if(i>=0)state.inventory.splice(i,1);state.gold+=4;notify(`${item} sold · 4 crowns`);save();openPanel('merchant')}else return;save();updateHud()}

